const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const PATH = '/webhook/lendloop-request';

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'];
let raw = null;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch {
  // A multipart request has no raw body, and it must get a 401 like any other bad call.
}

function check() {
  if (!timestamp || !signature) return 'missing';
  if (!/^\d{1,12}$/.test(timestamp)) return 'malformed';
  const match = /^v1=([0-9a-f]{64})$/.exec(signature);
  if (!match || raw === null) return 'malformed';
  if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > MAX_SKEW_SECONDS) return 'expired';
  const expected = crypto
    .createHmac('sha256', $env.CONVEX_TO_N8N_SECRET)
    .update(`v1:${timestamp}:POST:${PATH}:${raw}`)
    .digest();
  const given = Buffer.from(match[1], 'hex');
  return crypto.timingSafeEqual(expected, given) ? null : 'mismatch';
}

const problem = check();
if (problem) {
  console.log(`[signature rejected] reason=${problem}`);
  return [{ json: { valid: false, reason: problem } }];
}
return [{ json: { valid: true, payload: JSON.parse(raw) } }];

function clean(text) {
  // A value with a line break could forge a log entry.
  return String(text).replace(/[\u0000-\u001f\u007f]/g, ' ');
}

function mask(email) {
  const [name, domain] = String(email).split('@');
  return `${(name || '').slice(0, 1)}***@${domain || ''}`;
}

const MESSAGES = {
  created: (p) => `${p.toolName}: you have a new borrow request for ${p.startDate} to ${p.endDate}.`,
  approved: (p) => `${p.toolName}: your request for ${p.startDate} to ${p.endDate} was approved. Arrange pickup with ${p.contact.firstName} at ${mask(p.contact.email)}.`,
  declined: (p) => `${p.toolName}: your request for ${p.startDate} to ${p.endDate} was declined.`,
  cancelled: (p) => `${p.toolName}: the request for ${p.startDate} to ${p.endDate} was cancelled.`,
  returned: (p) => `${p.toolName}: the loan is marked as returned. Thank you.`,
};

const p = $input.first().json.payload;
const text = MESSAGES[p.event]
  ? MESSAGES[p.event](p)
  : `${p.toolName}: request status is now ${p.event}.`;
console.log(clean(`[mock notification] event=${p.eventId} to=${mask(p.recipient.email)} message="Hi ${p.recipient.firstName}, ${text}"`));
return [{ json: { eventId: p.eventId, delivered: true } }];
